WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_ex_b_judge'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '最大最小值判断', 'kp-ex-b-judge', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "最值基础判别"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心理念：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "最不利原则。求“至少……才能保证……”，必须先考虑最倒霉的情况！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[找出题干要求的满足条件] --> B[构思一个完全避开该条件的'最倒霉'抓取顺序]\nB --> C[把所有不符合条件的元素全部抓光]\nC --> D[最后再抓 1 个, 此时必然满足条件]\nD --> E[最倒霉数量 + 1 = 保证数量]"}}]}$$ AS jsonb), NULL, '最大最小值判断的核心考点与实战推导。', category_node.id, CAST('["数量关系", "最大最小值判断"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_ex_b_judge", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
